#include <stdio.h>

int sum(int a[], int n) {
    if (n == 0) {
        return 0;
    }
    return a[n - 1] + sum(a, n - 1);
}

int main(void) {
    int nums[{n}];

    for (int i = 0; i < {n}; i++) {
        if (scanf("%d", &nums[i]) != 1) {
            return 1;
        }
    }

    printf("一共 %d 条喵\n", sum(nums, {n}));
    return 0;
}
